package com.pp.shaderlod.optimization;
import com.pp.shaderlod.*;import com.pp.shaderlod.packs.*;import com.google.common.collect.*;import net.irisshaders.iris.shaderpack.include.*;import net.irisshaders.iris.shaderpack.option.*;import java.nio.file.*;import java.util.*;import java.util.zip.*;
public final class BlissCompileChecksMain {
 static int checks;static void check(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}
 public static void main(String[]args)throws Exception {
  Path base=Path.of(args[0]);Files.createDirectories(base);OptimizationConfig.load(base.resolve("flags.properties"));var nodes=ImmutableMap.<AbsolutePackPath,FileNode>builder();int definitions=0;
  try(var zip=new ZipFile(args[1])){for(var entry:Collections.list(zip.entries())){if(!entry.getName().startsWith("shaders/")||!entry.getName().matches(".*\\.(glsl|fsh|vsh)$"))continue;String text=new String(zip.getInputStream(entry).readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);var lines=text.lines().filter(line->line.contains("SHADERLOD_BLISS_PIXEL_GRAPH")).toList();if(lines.isEmpty())continue;definitions+=lines.stream().filter(line->line.trim().startsWith("#define SHADERLOD_BLISS_PIXEL_GRAPH ")).count();var path=AbsolutePackPath.fromAbsolutePath("/"+entry.getName().substring(8));nodes.put(path,new FileNode(path,ImmutableList.copyOf(lines)));}}
  check(definitions>0,"actual sealed source contains control definition");var ctor=IncludeGraph.class.getDeclaredConstructor(ImmutableMap.class,ImmutableMap.class);ctor.setAccessible(true);var opts=new ShaderPackOptions(ctor.newInstance(nodes.buildOrThrow(),ImmutableMap.of()),Map.of());var actual=CompileOptionControl.readOptions(opts,Map.of(),false);String key=CompileOptionControl.BLISS_PIXEL_GRAPH;check(CompileOptionControl.declaredContract(key,actual.get(key)),"real Iris isolated exact-source control STRING0/1/default0");
  var loaded=new ShaderPackOptions(ctor.newInstance(nodes.buildOrThrow(),ImmutableMap.of()),Map.of(key,"1"));for(String dim:List.of("minecraft:overworld","minecraft:the_nether","minecraft:the_end","custom:moon"))check(CompileOptionControl.loadedGraphNeedsDimensionRollback(loaded,dim)==!dim.equals("minecraft:overworld"),"actual typed loaded graph dimension rollback");
  var recipe=com.google.gson.JsonParser.parseString(Files.readString(Path.of(args[2]))).getAsJsonObject();check(CompileOptionControl.recipeKeys(CompileOptionControl.Family.BLISS,recipe).equals(Set.of(key)),"explicit pinned recipe control");var core=new CoreUniformFrame.Core(new LodSettings(true,32,96,8,false),LodPreset.PERFORMANCE);var flags=OptimizationSnapshot.noneRequested().with(OptimizationId.PIXEL_SCALE,true);
  for(String dim:List.of("minecraft:overworld","minecraft:the_nether","minecraft:the_end","custom:moon","unavailable"))for(boolean dh:List.of(false,true))for(boolean voxy:List.of(false,true)){var plan=CompileOptionControl.plan(CompileOptionControl.Family.BLISS,core,flags,Set.of(key),actual,dim,dh,voxy,Map.of(OptimizationId.PIXEL_SCALE,true));check(plan.get(key).equals(dim.equals("minecraft:overworld")&&!dh&&!voxy?"1":"0"),"sealed OW-only source/dimension/dependencies");}
  check(CompileOptionControl.plan(CompileOptionControl.Family.BLISS,core,flags,Set.of(key),actual,"minecraft:overworld",false,false,Map.of()).get(key).equals("0"),"absent real setup admission native0");check(CompileOptionControl.plan(CompileOptionControl.Family.BLISS,new CoreUniformFrame.Core(core.settings(),LodPreset.QUALITY),flags,Set.of(key),actual,"minecraft:overworld",false,false,Map.of(OptimizationId.PIXEL_SCALE,true)).get(key).equals("0"),"Quality native0");
  Path dir=Files.createTempDirectory(base,"source-case-");Files.copy(Path.of("dependencies/upstream/other-pack-research/Bliss_v2.1.2_(Chocapic13_Shaders_edit).zip"),dir.resolve("Original.zip"));Files.writeString(dir.resolve("Original.zip.txt"),"# personal retained\n"+key+"=0\n");var on=new PackSelectionService().apply(dir,"Original.zip",true,LodPreset.PERFORMANCE,Map.of(),false);check(on.accepted(),"genuine public R10 selection");Path generated=dir.resolve(on.packFile());var choice=new TreeMap<String,String>();choice.put("SHADERLOD_EFFECT_ADAPTER","1");for(String value:List.of("0","1")){choice.put(key,value);check("bliss-shader".equals(PackSelectionService.verifyGeneratedRendererGraph(generated,choice)),"genuine source/state semantic control choice");}for(String value:List.of("2","true")){choice.put(key,value);check(PackSelectionService.verifyGeneratedRendererGraph(generated,choice)==null,"invalid choice refused");}choice.remove(key);check(PackSelectionService.verifyGeneratedRendererGraph(generated,choice)==null,"missing private base control refused");choice.put(key,"1");choice.put("SHADERLOD_MAKEUP_AO_HALF_RES","1");check(PackSelectionService.verifyGeneratedRendererGraph(generated,choice)==null,"foreign graph refused");choice.remove("SHADERLOD_MAKEUP_AO_HALF_RES");var off=new PackSelectionService().apply(dir,on.packFile(),false,LodPreset.PERFORMANCE,choice,false);check(off.accepted()&&Files.readString(dir.resolve("Original.zip.txt")).contains(key+"=0"),"Off original preference preserved");
  var second=new PackSelectionService().apply(dir,"Original.zip",true,LodPreset.PERFORMANCE,Map.of(),false);check(second.accepted(),"public second selection");var quality=new PackSelectionService().apply(dir,second.packFile(),true,LodPreset.QUALITY,choice,false);check(quality.accepted()&&quality.packFile().equals("Original.zip")&&Files.readString(dir.resolve("Original.zip.txt")).contains(key+"=0"),"Quality original private preference preserved");var third=new PackSelectionService().apply(dir,"Original.zip",true,LodPreset.PERFORMANCE,Map.of(),false);check(third.accepted(),"public source refusal preparation");Path mutated=dir.resolve(third.packFile());String originalPersonal=Files.readString(dir.resolve("Original.zip.txt"));try(var fs=FileSystems.newFileSystem(mutated,Map.of())){Path shader=fs.getPath("/shaders/lib/shaderlod/adapter.glsl");if(!Files.exists(shader)){try(var paths=Files.walk(fs.getPath("/shaders"))){shader=paths.filter(Files::isRegularFile).filter(x->x.toString().endsWith(".glsl")).findFirst().orElseThrow();}}Files.writeString(shader,Files.readString(shader)+"\n// tamper\n");}check(PackSelectionService.verifyGeneratedRendererGraph(mutated,choice)==null,"mutated generated source refused");check(Files.readString(dir.resolve("Original.zip.txt")).equals(originalPersonal),"source refusal preserves personal original bytes");
  System.out.println("PASS "+checks+" Bliss exact-source isolated typed control/domain/public choices/restoration; full actual loaded native map and single-Apply driver activation remain unverified");
 }
}
